FUNCTION_BLOCK FB_PID
VAR_INPUT
    SP : REAL; (* Consigna *)
    PV : REAL; (* Variable de proceso *)
    Kp : REAL; (* Ganancia proporcional *)
    Ti : REAL; (* Tiempo integral en segundos *)
    Td : REAL; (* Tiempo derivativo en segundos *)
    ciclo : TIME; (* Periodo de muestreo *)
END_VAR
VAR_OUTPUT
    CV : REAL; (* Variable de control (0.0 a 100.0) *)
END_VAR
VAR
    e : REAL; (* Error actual *)
    e_prev : REAL; (* Error del ciclo anterior *)
    integral_acc : REAL; (* Acumulador de la integral del error *)
    dt_sec : REAL; (* Tiempo de ciclo en segundos *)
    deriv : REAL; (* Derivada del error *)
    I_term : REAL; (* Termino integral *)
    D_term : REAL; (* Termino derivativo *)
    CV_temp : REAL; (* Variable de control sin limitar *)
END_VAR

(* Conversion del tiempo de ciclo a segundos *)
dt_sec := TIME_TO_REAL(ciclo) / 1000.0;

(* Calculo del error *)
e := SP - PV;

(* Accion Integral con Anti-windup por clamping *)
IF Ti > 0.0 THEN
    (* Evita acumular error positivo si CV esta al 100%, o negativo si CV esta al 0% *)
    IF NOT ((CV >= 100.0 AND e > 0.0) OR (CV <= 0.0 AND e < 0.0)) THEN
        integral_acc := integral_acc + (e * dt_sec);
    END_IF;
    I_term := integral_acc / Ti;
ELSE
    integral_acc := 0.0;
    I_term := 0.0;
END_IF;

(* Accion Derivativa *)
IF dt_sec > 0.0 THEN
    deriv := (e - e_prev) / dt_sec;
ELSE
    deriv := 0.0;
END_IF;
D_term := Td * deriv;

(* Ecuacion PID estandar *)
CV_temp := Kp * (e + I_term + D_term);

(* Limitacion de la salida (0.0 a 100.0) *)
IF CV_temp > 100.0 THEN
    CV := 100.0;
ELSIF CV_temp < 0.0 THEN
    CV := 0.0;
ELSE
    CV := CV_temp;
END_IF;

(* Actualizacion del error para el calculo derivativo del proximo ciclo *)
e_prev := e;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_PID
VAR_INPUT
    SP : REAL;      // Consigna (Setpoint)
    PV : REAL;      // Variable de proceso
    Kp : REAL;      // Ganancia proporcional
    Ti : REAL;      // Tiempo integral (segundos)
    Td : REAL;      // Tiempo derivativo (segundos)
    ciclo : TIME;   // Período de muestreo
END_VAR

VAR_OUTPUT
    CV : REAL;      // Variable de control (0.0 a 100.0 %)
END_VAR

VAR
    e : REAL;           // Error actual
    e_prev : REAL;      // Error del ciclo anterior
    de_dt : REAL;       // Derivada del error
    dt : REAL;          // Tiempo de ciclo en segundos
    I_sum : REAL;       // Sumatoria de la integral del error
    I_new : REAL;       // Valor tentativo de la integral
    CV_tentative : REAL;// Salida tentativa para evaluar saturación
END_VAR

// Convertir tiempo de ciclo a segundos (REAL)
dt := TIME_TO_REAL(ciclo) / 1000.0;

// Evitar división por cero si el tiempo de ciclo es muy pequeño o cero
IF dt <= 0.0 THEN
    dt := 0.001;
END_IF;

// Cálculo del error (Acción directa: CV aumenta si PV < SP)
e := SP - PV;

// Cálculo de la derivada del error
de_dt := (e - e_prev) / dt;

// Acción Integral con Anti-windup (Clamping)
IF Ti > 0.0 THEN
    // Calcular integral tentativa
    I_new := I_sum + (e * dt);

    // Calcular salida tentativa para evaluar saturación
    CV_tentative := Kp * (e + (I_new / Ti) + (Td * de_dt));

    // Lógica de Clamping: evitar acumulación si satura en la misma dirección del error
    IF (CV_tentative >= 100.0 AND e > 0.0) OR (CV_tentative <= 0.0 AND e < 0.0) THEN
        // No se actualiza I_sum (se congela la integral)
    ELSE
        I_sum := I_new; // Se actualiza la integral
    END_IF;
ELSE
    I_sum := 0.0; // Desactivar acción integral si Ti <= 0.0
END_IF;

// Cálculo de la salida final (CV) antes de límites
IF Ti > 0.0 THEN
    CV := Kp * (e + (I_sum / Ti) + (Td * de_dt));
ELSE
    CV := Kp * (e + (Td * de_dt));
END_IF;

// Limitar la salida al rango 0.0 - 100.0 %
IF CV > 100.0 THEN
    CV := 100.0;
ELSIF CV < 0.0 THEN
    CV := 0.0;
END_IF;

// Guardar el error actual para el cálculo derivativo del próximo ciclo
e_prev := e;

END_FUNCTION_BLOCK

