    e_prev : REAL; (* Error del ciclo anterior *)
    integral : REAL; (* Acumulador de la integral del error *)
    dt : REAL; (* Tiempo de ciclo en segundos *)
    P_term : REAL; (* Accion proporcional *)
    I_term : REAL; (* Accion integral *)
    D_term : REAL; (* Accion derivativa *)
    CV_unc : REAL; (* Salida calculada sin limitar *)
END_VAR

(* Conversion del tiempo de ciclo a segundos *)
dt := TIME_TO_REAL(ciclo) / 1000.0;
IF dt <= 0.0 THEN
    dt := 0.001; (* Evitar division por cero *)
END_IF;

(* Calculo del error *)
e := SP - PV;

(* Accion proporcional *)
P_term := Kp * e;

(* Accion derivativa sobre el error *)
D_term := Kp * Td * ((e - e_prev) / dt);

(* Accion integral y calculo de salida sin limitar *)
IF Ti > 0.0 THEN
    (* Se evalua con la integral tentativa para el ciclo actual *)
    I_term := Kp * ((integral + (e * dt)) / Ti);
ELSE
    I_term := 0.0;
    integral := 0.0;
END_IF;

CV_unc := P_term + I_term + D_term;

(* Anti-windup por clamping: actualizacion del acumulador integral *)
IF Ti > 0.0 THEN
    (* No acumula si esta saturado al maximo y el error es positivo, o saturado al minimo y el error es negativo *)
    IF NOT ((CV_unc >= 100.0 AND e > 0.0) OR (CV_unc <= 0.0 AND e < 0.0)) THEN
        integral := integral + (e * dt);
    END_IF;
END_IF;

(* Limitacion de la salida CV al rango 0.0 - 100.0 *)
IF CV_unc > 100.0 THEN
    CV := 100.0;
ELSIF CV_unc < 0.0 THEN
    CV := 0.0;
ELSE
    CV := CV_unc;
END_IF;

(* Memoria del error para la derivada en el proximo ciclo *)
e_prev := e;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_PID
VAR_INPUT
    SP : REAL;  // Setpoint
    PV : REAL;  // Process Variable
    Kp : REAL;  // Proportional Gain
    Ti : REAL;  // Integral Time (seconds)
    Td : REAL;  // Derivative Time (seconds)
    ciclo : TIME;  // Sampling period
END_VAR

VAR_OUTPUT
    CV : REAL;  // Control Variable (0.0 to 100.0)
END_VAR

VAR
    e : REAL;  // Error
    e_prev : REAL;  // Previous Error
    integral : REAL;  // Integral of error
    derivative : REAL;  // Derivative of error
    dt : TIME;  // Time difference
    dt_sec : REAL;  // Time difference in seconds
    integral_limit : REAL;  // Limit for integral to prevent windup
END_VAR

// Calculate error
e := SP - PV;

// Calculate time difference in seconds
dt := ciclo;
dt_sec := dt / 1.0s;  // Convert TIME to REAL seconds

// Proportional term
CV := Kp * e;

// Integral term
IF Ti > 0.0 THEN
    integral := integral + (e * dt_sec);
    integral_limit := 100.0 / Kp;
    IF CV >= 100.0 THEN
        integral := integral - (e * dt_sec);
    ELSIF CV <= 0.0 THEN
        integral := integral - (e * dt_sec);
    END_IF;
    CV := CV + (Kp / Ti) * integral;
END_IF;

// Derivative term
derivative := (e - e_prev) / dt_sec;
CV := CV + Kp * Td * derivative;

// Clamp CV to 0.0 to 100.0
IF CV > 100.0 THEN
    CV := 100.0;
ELSIF CV < 0.0 THEN
    CV := 0.0;
END_IF;

// Update previous error
e_prev := e;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_PID
VAR_INPUT
    SP : REAL;      // Consigna (Setpoint)
    PV : REAL;      // Variable de proceso (Process Variable)
    Kp : REAL;      // Ganancia proporcional
    Ti : REAL;      // Tiempo integral (segundos)
    Td : REAL;      // Tiempo derivativo (segundos)
    ciclo : TIME;   // Período de muestreo
END_VAR

VAR_OUTPUT
    CV : REAL;      // Variable de control (0.0 a 100.0 %)
END_VAR

VAR
    e : REAL;                   // Error actual
    e_prev : REAL := 0.0;       // Error del ciclo anterior
    integral_sum : REAL := 0.0; // Sumatoria de la integral del error
    dt : REAL;                  // Tiempo de ciclo en segundos
    P_term : REAL;              // Término proporcional
    I_term : REAL;              // Término integral
    D_term : REAL;              // Término derivativo
    CV_pre : REAL;              // Salida preliminar para evaluar saturación
    CV_raw : REAL;              // Salida calculada sin limitar
END_VAR

// Convertir el tiempo de ciclo a segundos
dt := TIME_TO_REAL(ciclo) / 1000.0;

// Cálculo del error (salida aumenta si PV < SP)
e := SP - PV;

// Cálculo del término proporcional
P_term := Kp * e;

// Cálculo del término derivativo (sobre el error)
IF dt > 0.0 THEN
    D_term := Kp * Td * (e - e_prev) / dt;
ELSE
    D_term := 0.0;
END_IF;

// Cálculo del término integral y Anti-windup (Clamping)
IF Ti > 0.0 THEN
    // Calcular salida preliminar con la integral del ciclo anterior
    I_term := (Kp / Ti) * integral_sum;
    CV_pre := P_term + I_term + D_term;

    // Anti-windup: evitar acumular error si la salida está saturada en la misma dirección
    IF (CV_pre >= 100.0 AND e > 0.0) OR (CV_pre <= 0.0 AND e < 0.0) THEN
        // No se acumula el error (Clamping activo)
    ELSE
        // Se acumula el error en la integral
        IF dt > 0.0 THEN
            integral_sum := integral_sum + (e * dt);
        END_IF;
    END_IF;

    // Recalcular el término integral con el valor actualizado
    I_term := (Kp / Ti) * integral_sum;
ELSE
    // Desactivar acción integral si Ti <= 0.0
    integral_sum := 0.0;
    I_term := 0.0;
END_IF;

// Suma total de la ecuación PID estándar
CV_raw := P_term + I_term + D_term;

// Limitación de la salida (0.0 a 100.0)
IF CV_raw > 100.0 THEN
    CV := 100.0;
ELSIF CV_raw < 0.0 THEN
    CV := 0.0;
ELSE
    CV := CV_raw;
END_IF;

// Actualizar el error para el cálculo derivativo del próximo ciclo
e_prev := e;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_PID
VAR_INPUT
    SP : REAL;      // Setpoint
    PV : REAL;      // Process Variable
    Kp : REAL;      // Proportional Gain
    Ti : REAL;      // Integral Time (seconds)
    Td : REAL;      // Derivative Time (seconds)
    ciclo : TIME;   // Sampling period
END_VAR

VAR_OUTPUT
    CV : REAL;      // Control Variable (output)
END_VAR

VAR
    e : REAL;               // Error
    e_prev : REAL;          // Previous error
    integral : REAL;        // Integral term
    derivative : REAL;      // Derivative term
    dt : REAL;              // Sampling period in seconds
    CV_unsat : REAL;        // Unsaturated control variable
END_VAR

VAR CONSTANT
    CV_MIN : REAL := 0.0;   // Minimum CV
    CV_MAX : REAL := 100.0; // Maximum CV
END_VAR

// Convert TIME to seconds
dt := TO_REAL(ciclo) / 1000.0;

// Calculate error
e := SP - PV;

// Proportional term
CV_unsat := Kp * e;

// Integral term
IF Ti > 0.0 THEN
    integral := integral + (e * dt / Ti);

    // Anti-windup: Clamping
    IF CV_unsat >= CV_MAX THEN
        IF e > 0.0 THEN
            integral := integral - (e * dt / Ti); // Prevent positive windup
        END_IF
    ELSIF CV_unsat <= CV_MIN THEN
        IF e < 0.0 THEN
            integral := integral - (e * dt / Ti); // Prevent negative windup
        END_IF
    END_IF
END_IF

// Add integral term
CV_unsat := CV_unsat + Kp * integral;

// Derivative term
derivative := Td * (e - e_prev) / dt;
CV_unsat := CV_unsat + Kp * derivative;

// Update previous error
e_prev := e;

// Saturate CV
IF CV_unsat > CV_MAX THEN
    CV := CV_MAX;
ELSIF CV_unsat < CV_MIN THEN
    CV := CV_MIN;
ELSE
    CV := CV_unsat;
END_IF

END_FUNCTION_BLOCK

